<div id="kt_content_container" class="container-xxl py-5"><div class="d-flex flex-wrap flex-stack mb-7"><div><h1 class="fw-bold text-gray-900 mb-2">Administrar Pedidos de Clientes</h1><div class="text-muted fs-6">Consulta clientes, domicilios y confirma pedidos</div></div></div><div id="alerta-admin-pedidos"></div><div class="card card-flush"><div class="card-body pt-0"><table class="table align-middle table-row-dashed fs-6 gy-5" id="tabla_admin_pedidos"><thead><tr class="text-start text-gray-500 fw-bold fs-7 text-uppercase gs-0"><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Estatus</th><th>Acciones</th></tr></thead><tbody></tbody></table></div></div></div>
<div class="modal fade" id="modal_admin_detalle" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered modal-lg"><div class="modal-content"><div class="modal-header"><h2 class="fw-bold">Detalle del Pedido</h2><button type="button" class="btn btn-icon btn-sm btn-active-light-primary" data-bs-dismiss="modal"><i class="ki-outline ki-cross fs-1"></i></button></div><div class="modal-body" id="admin_detalle_contenido"></div></div></div></div>
<script>
(function(){const alerta=document.getElementById('alerta-admin-pedidos');function estado(s){const e={1:['Pendiente','warning'],2:['Pagado / Enviado','primary'],3:['Entregado','success'],4:['Cancelado','danger']}[s]||['Desconocido','secondary'];return '<span class="badge badge-light-'+e[1]+'">'+e[0]+'</span>';}function cargar(){fetch('actions/16.read_pedidos.php').then(r=>r.json()).then(res=>{$('#tabla_admin_pedidos').DataTable({destroy:true,data:(res.data||[]).map(p=>['#'+p.id_pedido,p.usuario_nombre,p.fecha_pedido,'$'+Number(p.total).toFixed(2),estado(p.estatus),'<button class="btn btn-sm btn-light-info ver-admin" data-id="'+p.id_pedido+'">Ver detalles</button> '+(Number(p.estatus)===1?'<button class="btn btn-sm btn-light-primary confirmar-admin" data-id="'+p.id_pedido+'">Confirmar y descontar stock</button>':'')]),columns:[{title:'Pedido'},{title:'Cliente'},{title:'Fecha'},{title:'Total'},{title:'Estatus'},{title:'Acciones'}],pageLength:10,language:{url:'https://cdn.datatables.net/plug-ins/1.13.7/i18n/es-ES.json'}});}).catch(()=>alerta.innerHTML='<div class="alert alert-danger">No se pudieron cargar los pedidos.</div>');}$('#tabla_admin_pedidos').on('click','.ver-admin',function(){fetch('actions/16.read_pedidos.php?id_pedido='+$(this).data('id')).then(r=>r.json()).then(res=>{if(!res.success)return;const p=res.data;document.getElementById('admin_detalle_contenido').innerHTML='<div class="row g-5 mb-5"><div class="col-md-6"><strong>Cliente:</strong><br>'+p.usuario_nombre+'</div><div class="col-md-6"><strong>Domicilio:</strong><br>'+(p.domicilio||'<span class="text-danger">Sin domicilio registrado</span>')+'</div></div><div class="table-responsive"><table class="table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th></tr></thead><tbody>'+p.productos.map(i=>'<tr><td>'+i.producto_nombre+'</td><td>'+i.cantidad+'</td><td>$'+Number(i.precio_unitario).toFixed(2)+'</td></tr>').join('')+'</tbody></table></div><div class="text-end fw-bold fs-4">Total: $'+Number(p.total).toFixed(2)+' MXN</div>';bootstrap.Modal.getOrCreateInstance(document.getElementById('modal_admin_detalle')).show();});});$('#tabla_admin_pedidos').on('click','.confirmar-admin',function(){const datos=new FormData();datos.append('id_pedido',$(this).data('id'));datos.append('estatus',2);fetch('actions/17.update_estatus_pedido.php',{method:'POST',body:datos}).then(r=>r.json()).then(res=>{alerta.innerHTML='<div class="alert alert-'+(res.success?'success':'danger')+'">'+(res.message||res.error)+'</div>';if(res.success)cargar();});});cargar();})();
</script>
